import { EditorState, Compartment } from '@codemirror/state';
import { EditorView, keymap } from '@codemirror/view';
import { defaultKeymap, history, historyKeymap } from '@codemirror/commands';
import { markdown, markdownLanguage } from '@codemirror/lang-markdown';
import { Table } from '@lezer/markdown';

// Import from npm package
import {
  livePreviewPlugin,
  markdownStylePlugin,
  mathPlugin,
  blockMathField,
  tableField,
  tableEditorPlugin,
  codeBlockEditorPlugin,
  codeBlockField,
  imageField,
  linkPlugin,
  mouseSelectingField,
  collapseOnSelectionFacet,
  editorTheme,
  setMouseSelecting,
  initHighlighter,
} from 'codemirror-live-markdown';

// Initial document content
const basicDoc = `# Basic Table Preview

This editor uses the default table plugin.

### Table (source on cursor)

| Name  | Age | City     |
|-------|-----|----------|
| Alice | 25  | Beijing  |
| Bob   | 30  | Shanghai |

Click inside the table to switch to Markdown source.`;

const advancedDoc = `# Advanced Table Preview

This editor uses the advanced table plugin.

### Table (editable cells)

| Name  | Age | City     |
|-------|-----|----------|
| Alice | 25  | Beijing  |
| Bob   | 30  | Shanghai |

Edit cells directly in Live mode. Use the MD button to switch to source.`;

const codeInlineDoc = `# Code Block Inline Editing

This editor uses \`codeBlockField({ interaction: "inline" })\`.

### How to try

1. Code blocks show a **header** (language badge + Copy + MD) and **footer**.
2. **Click inside the code** to place your cursor and edit directly.
3. Syntax highlighting updates in real time as you type.
4. Click **MD** to switch to full source mode (showing \\\`\\\`\\\` fences).
5. Click **Code** to return to inline editing mode.

\`\`\`javascript
function sum(a, b) {
  return a + b;
}

console.log(sum(2, 3));
\`\`\`

\`\`\`python
def greet(name):
    return f"Hello, {name}"

print(greet("Lumina"))
\`\`\`

\`\`\`typescript
interface User {
  name: string;
  age: number;
}

const user: User = { name: "Alice", age: 25 };
\`\`\`

Try editing the code above — your cursor stays in place and highlighting refreshes live.
`;

const codeAutoDoc = `# Code Block Auto Preview

This editor uses \`codeBlockField()\` (auto mode, default).

### How to try

1. Code blocks are rendered with syntax highlighting by default.
2. **Move your cursor into** a code block to see the raw Markdown source.
3. **Move your cursor away** and the code block returns to rendered preview.

\`\`\`javascript
function sum(a, b) {
  return a + b;
}

console.log(sum(2, 3));
\`\`\`

\`\`\`python
def greet(name):
    return f"Hello, {name}"

print(greet("Lumina"))
\`\`\`

Try clicking inside a code block, then clicking outside — watch it toggle automatically.
`;

const codeToggleDoc = `# Code Block Toggle Preview

This editor uses \`codeBlockEditorPlugin()\` (toggle mode).

### How to try

1. Code blocks are rendered in Live mode by default.
2. Click the **MD** button in a code block to show Markdown source.
3. In source mode, click **Code** to switch back to rendered preview.

\`\`\`javascript
function sum(a, b) {
  return a + b;
}

console.log(sum(2, 3));
\`\`\`

\`\`\`python
def greet(name):
    return f"Hello, {name}"

print(greet("Lumina"))
\`\`\`
`;

const longDoc = `# Welcome to Live Preview! 🎉

This is a demonstration of **Live Preview** mode for CodeMirror 6, inspired by Obsidian.

## What is Live Preview?

Live Preview is a hybrid editing mode that combines the best of both worlds:
- **WYSIWYG** (What You See Is What You Get) - formatted text looks nice
- **Source editing** - you can still edit the raw Markdown

## Try it yourself!

Move your cursor into any of these formatted elements:

- **Bold text** - The \`**\` markers will smoothly appear
- *Italic text* - The \`*\` markers slide in
- ~~Strikethrough~~ - The \`~~\` markers show up
- \`inline code\` - The backticks become visible

### Math Formulas ✨

**Inline math:** The famous equation \`$E = mc^2$\` shows energy-mass equivalence.

**Block math:**

\`\`\`math
\\int_0^\\infty e^{-x^2} dx = \\frac{\\sqrt{\\pi}}{2}
\`\`\`

**More examples:**

- Pythagorean theorem: \`$a^2 + b^2 = c^2$\`
- Quadratic formula: \`$x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}$\`

\`\`\`math
\\sum_{n=1}^{\\infty} \\frac{1}{n^2} = \\frac{\\pi^2}{6}
\`\`\`

Click on any formula to edit it!

### Tables 📊

Tables stay in Live mode by default. Edit cells directly and use the MD button to switch to source:

| Name  | Age | City     |
|-------|-----|----------|
| Alice | 25  | Beijing  |
| Bob   | 30  | Shanghai |

Edit cells directly in the table. You can also use alignment:

| Left | Center | Right |
|:-----|:------:|------:|
| L    |   C    |     R |
| 1    |   2    |     3 |

### Code Blocks 💻

Code blocks with syntax highlighting:

\`\`\`javascript
function greet(name) {
  console.log(\`Hello, \${name}!\`);
  return { message: 'Welcome!' };
}

greet('World');
\`\`\`

\`\`\`python
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print([fibonacci(i) for i in range(10)])
\`\`\`

\`\`\`typescript
interface User {
  name: string;
  age: number;
}

const user: User = { name: 'Alice', age: 25 };
\`\`\`

Use the MD button on any code block to switch to source editing.

### Images 🖼️

Images are rendered inline when you're not editing them:

![CodeMirror Logo](https://codemirror.net/style/logo.svg)

![Placeholder Image](https://picsum.photos/400/200 "A placeholder image")

Click on any image to see the Markdown syntax!

### Links 🔗

Links are rendered as clickable text:

- [CodeMirror Website](https://codemirror.net)
- [GitHub](https://github.com "Visit GitHub")
- Check out the [documentation](https://codemirror.net/docs/)

**Wiki-style links:** [[Internal Page]] and [[Another Page|Custom Text]]

Click on any link to edit it!

### How does it work?

When your cursor is **outside** formatted text, the markers are hidden and you see the rendered effect. When you move your cursor **inside**, the markers smoothly animate into view so you can edit them.

## More Examples

### Lists

- First item
- Second item with **bold**
- Third item with *italic*
  - Nested item
  - Another nested

### Quotes

> This is a quote.
> It can span multiple lines.
> 
> Try clicking inside to see the \`>\` markers!

### Headers

# H1 Header
## H2 Header
### H3 Header
#### H4 Header

Move your cursor to any header to see the \`#\` symbols appear!

## Technical Details

This is built with:
- **CodeMirror 6** - Modern code editor
- **Custom ViewPlugins** - For the Live Preview logic
- **CSS Animations** - Smooth transitions using \`max-width\` and \`fontSize\`
- **KaTeX** - Beautiful math rendering

The core mechanism is the \`shouldShowSource()\` function that checks if the cursor intersects with a formatted element.

---

**Tip:** Try switching to "Source Mode" using the button above to see all the Markdown markers at once!
`;

// Initialize syntax highlighter then create editors
(async () => {
await initHighlighter();

// Compartment for dynamic mode switching
const modeCompartment = new Compartment();

function setupMouseSelecting(view: EditorView) {
  view.contentDOM.addEventListener('mousedown', () => {
    view.dispatch({ effects: setMouseSelecting.of(true) });
  });

  document.addEventListener('mouseup', () => {
    requestAnimationFrame(() => {
      view.dispatch({ effects: setMouseSelecting.of(false) });
    });
  });
}

const basicModeCompartment = new Compartment();

const basicState = EditorState.create({
  doc: `${basicDoc}\n\n${longDoc}`,
  extensions: [
    history(),
    keymap.of([...defaultKeymap, ...historyKeymap]),
    markdown({ base: markdownLanguage, extensions: [Table] }),
    EditorView.lineWrapping,
    basicModeCompartment.of([
      collapseOnSelectionFacet.of(true),
      mouseSelectingField,
      livePreviewPlugin,
      markdownStylePlugin,
      mathPlugin,
      blockMathField,
      tableField,
      codeBlockEditorPlugin(),
      imageField(),
      linkPlugin({
        openInNewTab: true,
        onWikiLinkClick: (link) => {
          alert(`Wiki link clicked: ${link}`);
        },
      }),
    ]),
    editorTheme,
  ],
});

const basicView = new EditorView({
  state: basicState,
  parent: document.getElementById('editor-basic')!,
});

setupMouseSelecting(basicView);

const advancedState = EditorState.create({
  doc: advancedDoc,
  extensions: [
    history(),
    keymap.of([...defaultKeymap, ...historyKeymap]),
    markdown({ base: markdownLanguage, extensions: [Table] }),
    EditorView.lineWrapping,
    collapseOnSelectionFacet.of(true),
    mouseSelectingField,
    markdownStylePlugin,
    tableEditorPlugin(),
    editorTheme,
  ],
});

const advancedView = new EditorView({
  state: advancedState,
  parent: document.getElementById('editor-advanced')!,
});

setupMouseSelecting(advancedView);

const codeAutoState = EditorState.create({
  doc: codeAutoDoc,
  extensions: [
    history(),
    keymap.of([...defaultKeymap, ...historyKeymap]),
    markdown({ base: markdownLanguage, extensions: [Table] }),
    EditorView.lineWrapping,
    collapseOnSelectionFacet.of(true),
    mouseSelectingField,
    livePreviewPlugin,
    markdownStylePlugin,
    codeBlockField(),
    editorTheme,
  ],
});

const codeAutoView = new EditorView({
  state: codeAutoState,
  parent: document.getElementById('editor-code-auto')!,
});

setupMouseSelecting(codeAutoView);

const codeInlineState = EditorState.create({
  doc: codeInlineDoc,
  extensions: [
    history(),
    keymap.of([...defaultKeymap, ...historyKeymap]),
    markdown({ base: markdownLanguage, extensions: [Table] }),
    EditorView.lineWrapping,
    collapseOnSelectionFacet.of(true),
    mouseSelectingField,
    livePreviewPlugin,
    markdownStylePlugin,
    codeBlockField({ interaction: 'inline', copyButton: true }),
    editorTheme,
  ],
});

const codeInlineView = new EditorView({
  state: codeInlineState,
  parent: document.getElementById('editor-code-inline')!,
});

setupMouseSelecting(codeInlineView);

const codeToggleState = EditorState.create({
  doc: codeToggleDoc,
  extensions: [
    history(),
    keymap.of([...defaultKeymap, ...historyKeymap]),
    markdown({ base: markdownLanguage, extensions: [Table] }),
    EditorView.lineWrapping,
    collapseOnSelectionFacet.of(true),
    mouseSelectingField,
    livePreviewPlugin,
    markdownStylePlugin,
    codeBlockEditorPlugin(),
    editorTheme,
  ],
});

const codeToggleView = new EditorView({
  state: codeToggleState,
  parent: document.getElementById('editor-code-toggle')!,
});

setupMouseSelecting(codeToggleView);

const basicLiveBtn = document.getElementById('basicLiveBtn')!;
const basicSourceBtn = document.getElementById('basicSourceBtn')!;

basicLiveBtn.addEventListener('click', () => {
  basicView.dispatch({
    effects: basicModeCompartment.reconfigure([
      collapseOnSelectionFacet.of(true),
      mouseSelectingField,
      livePreviewPlugin,
      markdownStylePlugin,
      mathPlugin,
      blockMathField,
      tableField,
      codeBlockEditorPlugin(),
      imageField(),
      linkPlugin({
        openInNewTab: true,
        onWikiLinkClick: (link) => {
          alert(`Wiki link clicked: ${link}`);
        },
      }),
    ]),
  });
  basicLiveBtn.classList.add('active');
  basicSourceBtn.classList.remove('active');
});

basicSourceBtn.addEventListener('click', () => {
  basicView.dispatch({
    effects: basicModeCompartment.reconfigure([
      collapseOnSelectionFacet.of(false),
      markdownStylePlugin,
    ]),
  });
  basicSourceBtn.classList.add('active');
  basicLiveBtn.classList.remove('active');
});

})();

