1	import { EditorState } from '@codemirror/state';
2	import { collapseOnSelectionFacet } from './facets';
3	import { mouseSelectingField } from './mouseSelecting';
4	
5	/**
6	 * Determine whether the specified range should show source code
7	 *
8	 * This is the core decision function for Live Preview, determining whether
9	 * an element should display source code or rendered output.
10	 *
11	 * @param state - Editor state
12	 * @param from - Element start position
13	 * @param to - Element end position
14	 * @returns true = show source, false = show rendered output
15	 *
16	 * @example
17	 * ```typescript
18	 * // Document content: "Hello **world** test"
19	 * // Positions:         0     6    13   18
20	 *
21	 * // Case 1: Cursor after "Hello" (position 5)
22	 * shouldShowSource(state, 6, 15) // false - hide **, show bold effect
23	 *
24	 * // Case 2: Cursor in middle of "world" (position 10)
25	 * shouldShowSource(state, 6, 15) // true - show **, editable
26	 *
27	 * // Case 3: Selection spans across (positions 4-12)
28	 * shouldShowSource(state, 6, 15) // true - show **, editable
29	 * ```
30	 */
31	export const shouldShowSource = (state: EditorState, from: number, to: number): boolean => {
32	  // 1. Check if Live Preview is enabled
33	  const shouldCollapse = state.facet(collapseOnSelectionFacet);
34	  if (!shouldCollapse) {
35	    return false; // Not enabled, always show source
36	  }
37	
38	  // 2. Don't show source during drag selection (avoid flickering)
39	  const isDragging = state.field(mouseSelectingField, false);
40	  if (isDragging) {
41	    return false;
42	  }
43	
44	  // 3. Check if cursor touches the target range
45	  for (const range of state.selection.ranges) {
46	    // Show source if there's any intersection
47	    if (range.from <= to && range.to >= from) {
48	      return true;
49	    }
